import { appendFileSync, chmodSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";
import { runSensoryCommand } from "./native_helper.js";

export interface ClipboardSnapshot {
  changeCount: number;
  skippedConcealed: boolean;
  concealedTypes: string[];
  text: string | null;
  frontmostApp: string | null;
  windowTitle: string | null;
}

const CONCEALED_PASTEBOARD_TYPES = new Set([
  "org.nspasteboard.ConcealedType",
  "org.nspasteboard.TransientType",
  "org.nspasteboard.AutoGeneratedType",
  "com.agilebits.onepassword",
  "com.typeit4me.clipping",
  "de.petermaurer.TransientPasteboardType",
]);

export function hasConcealedPasteboardType(types: string[]): { concealed: boolean; matched: string[] } {
  const matched = types.filter((t) => {
    if (CONCEALED_PASTEBOARD_TYPES.has(t)) return true;
    const lower = t.toLowerCase();
    return lower.includes("concealed") || lower.includes("onepassword") || lower.includes("transient");
  });
  return { concealed: matched.length > 0, matched };
}

export function readSafeClipboard(binDir?: string): ClipboardSnapshot {
  const raw = runSensoryCommand<{
    changeCount: number;
    skippedConcealed: boolean;
    concealedTypes: string[];
    text?: string | null;
    frontmostApp?: string | null;
    windowTitle?: string | null;
  }>(["clipboard"], binDir);

  const check = hasConcealedPasteboardType(raw.concealedTypes ?? []);
  if (raw.skippedConcealed || check.concealed) {
    return {
      changeCount: raw.changeCount,
      skippedConcealed: true,
      concealedTypes: check.matched.length > 0 ? check.matched : raw.concealedTypes,
      text: null,
      frontmostApp: raw.frontmostApp ?? null,
      windowTitle: raw.windowTitle ?? null,
    };
  }

  return {
    changeCount: raw.changeCount,
    skippedConcealed: false,
    concealedTypes: [],
    text: raw.text ?? null,
    frontmostApp: raw.frontmostApp ?? null,
    windowTitle: raw.windowTitle ?? null,
  };
}

export function captureClipboardOnce(options: {
  captureJsonlPath: string;
  lastChangeCount?: number;
  workspacePath?: string;
  binDir?: string;
}): { captured: boolean; snapshot: ClipboardSnapshot } {
  const snap = readSafeClipboard(options.binDir);
  if (
    snap.skippedConcealed ||
    !snap.text ||
    snap.text.trim().length === 0 ||
    (options.lastChangeCount !== undefined && snap.changeCount === options.lastChangeCount)
  ) {
    return { captured: false, snapshot: snap };
  }

  mkdirSync(dirname(options.captureJsonlPath), { recursive: true, mode: 0o700 });
  const record = {
    ts: Date.now(),
    changeCount: snap.changeCount,
    text: snap.text,
    frontmostApp: snap.frontmostApp,
    windowTitle: snap.windowTitle,
    cwd: options.workspacePath ?? process.cwd(),
  };
  appendFileSync(options.captureJsonlPath, `${JSON.stringify(record)}\n`, { mode: 0o600 });
  try {
    chmodSync(options.captureJsonlPath, 0o600);
  } catch {
    // ignore
  }
  return { captured: true, snapshot: snap };
}
